\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}


\pagestyle{empty}
\begin{tikzpicture}[scale=1.5, rotate=0]

% Real side length
% Should be fixed
\def\r{0.75}

% Marks on axes 
\def\mr{1} % change this

% Normal vector length (relative to r) 
\def\nl{1.3}

\def\arrowcolor{orangepeel}

\def\nsamples{20}


\begin{axis}[
		scale=1.25,
		clip=false,
		view={120}{20},
		hide axis,
		xmin=-1.5,xmax=1.5,
		ymin=-1.5,ymax=1.5,
		zmin=-1.3,zmax=1.3,
	]

   \plot3[
   		surf,
		shader = faceted interp,
		opacity=1,
		samples = \nsamples,
		samples y=\nsamples,
		draw=deepskyblue!90!black, very thin,
		colormap={custom}{color(0)=(deepskyblue!70) color(1)=(deepskyblue!10)},
		z buffer=sort, domain=0:180, y domain=0:360
	] ({\r*sin(x)*cos(y)},
       {\r*sin(x)*sin(y)},
       {\r*cos(x)});;

% Axes
\def\axwidth{0.6}

% X
\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:\r,0,0);

% Y
\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:0,\r,0);

% Z
\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:0,0,\r);

% Ticks

\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[below, yshift=0pt]: \tiny $\mr$}] 
	at (axis cs:\r,0,0) {};
\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[below, xshift=0pt, yshift=0pt]: \tiny $\mr$}] 
	at (axis cs:0,\r,0) {};
\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[left, xshift=1pt, yshift=0pt]: \tiny $\mr$}] 
	at (axis cs:0,0,\r) {};

%% Normal vectors
\node[circle, draw=none, fill=\arrowcolor, inner sep=0.75pt] 
	at (axis cs:{\r*sin(45)*cos(45)},{\r*sin(45)*sin(45)},{\r*cos(45)}) {};
\draw[\arrowcolor, line width=\axwidth*1.5, -latex] 
	(axis cs:{\r*sin(45)*cos(45)},{\r*sin(45)*sin(45)},{\r*cos(45)}) -- 
	(axis cs:{(\r+\r*\nl)*sin(45)*cos(45)},{(\r+\r*\nl)*sin(45)*sin(45)},{(\r+\r*\nl)*cos(45)}) 
	node[right, black] {\scriptsize $\mathbf{n}$};

% X-cont.
\draw[line width=\axwidth, -stealth] (axis cs:\r,0,0) -- (axis cs:2,0,0)
		node[left, xshift=4pt, yshift=-3pt] {\scriptsize $x$}; 

% Y-cont.
\draw[line width=\axwidth, -stealth] (axis cs:0,\r,0) -- (axis cs:0,1.5,0)
		node[right, yshift=-2pt] {\scriptsize $y$};
% Z-cont.
\draw[line width=\axwidth, -stealth] (axis cs:0,0,\r) -- (axis cs:0,0,1.5)
		node[above] {\scriptsize $z$};  

\end{axis}
\end{tikzpicture}
\end{document}

